+"use server";
+
+import { z } from "zod";
+import { revalidatePath } from "next/cache";
+import { requireRole } from "@/lib/auth";
+import { createClient } from "@/lib/supabase/server";
+import { getPayments } from "@/lib/integrations/payments";
+import { cancellationOutcome } from "@/lib/pricing";
+
+const uuid = z.string().uuid();
+
+/** Save a listener to the customer's favorites (idempotent). */
+export async function addFavorite(
+  providerId: string,
+): Promise<{ ok: boolean }> {
+  const profile = await requireRole("customer");
+  if (!uuid.safeParse(providerId).success) return { ok: false };
+  const supabase = await createClient();
+  const { error } = await supabase
+    .from("favorites")
+    .upsert(
+      { customer_id: profile.id, provider_id: providerId },
+      { onConflict: "customer_id,provider_id", ignoreDuplicates: true },
+    );
+  if (error) return { ok: false };
+  revalidatePath("/account");
+  return { ok: true };
+}
+
+/** Remove a listener from the customer's favorites. */
+export async function removeFavorite(
+  providerId: string,
+): Promise<{ ok: boolean }> {
+  const profile = await requireRole("customer");
+  const supabase = await createClient();
+  const { error } = await supabase
+    .from("favorites")
+    .delete()
+    .eq("customer_id", profile.id)
+    .eq("provider_id", providerId);
+  if (error) return { ok: false };
+  revalidatePath("/account");
+  return { ok: true };
+}
+
+export interface CancelResult {
+  ok: boolean;
+  released?: boolean;
+  error?: string;
+}
+
+/**
+ * Cancel a confirmed booking. Cancellation policy (SPEC §5): a scheduled session
+ * cancelled ≥1h before its start releases the hold, otherwise the block is
+ * charged. A "now" booking that was never joined releases (the customer never
+ * talked — "you're in control, leave any time"). Capture/refund go through the
+ * payments adapter.
+ */
+export async function cancelBooking(bookingId: string): Promise<CancelResult> {
+  const profile = await requireRole("customer");
+  const supabase = await createClient();
+
+  const { data: booking } = await supabase
+    .from("bookings")
+    .select("*")
+    .eq("id", bookingId)
+    .maybeSingle();
+  if (!booking || booking.customer_id !== profile.id) {
+    return { ok: false, error: "Booking not found." };
+  }
+  if (booking.status !== "confirmed") {
+    return { ok: false, error: "This booking can't be cancelled." };
+  }
+
+  let release: boolean;
+  if (booking.start_mode === "scheduled") {
+    release =
+      cancellationOutcome({
+        priceBlockCents: booking.price_block_cents,
+        scheduledAt: booking.scheduled_at,
+        nowMs: Date.now(),
+      }).action === "release";
+  } else {
+    release = true; // a "now" booking that was never joined
+  }
+
+  const payments = getPayments();
+  if (booking.payment_ref) {
+    if (release) {
+      await payments.refund({
+        paymentRef: booking.payment_ref,
+        amountCents: booking.price_block_cents,
+      });
+    } else {
+      await payments.capture({
+        paymentRef: booking.payment_ref,
+        amountCents: booking.price_block_cents,
+      });
+    }
+  }
+
+  const { error } = await supabase
+    .from("bookings")
+    .update({ status: "cancelled" })
+    .eq("id", bookingId);
+  if (error) return { ok: false, error: "Could not cancel the booking." };
+
+  revalidatePath("/account");
+  return { ok: true, released: release };
+}
+
+const rescheduleSchema = z.object({
+  bookingId: uuid,
+  scheduledAt: z.string().datetime(),
+});
+
+/** Move a confirmed booking to a new future time. */
+export async function rescheduleBooking(input: {
+  bookingId: string;
+  scheduledAt: string;
+}): Promise<{ ok: boolean; error?: string }> {
+  const profile = await requireRole("customer");
+  const parsed = rescheduleSchema.safeParse(input);
+  if (!parsed.success) return { ok: false, error: "Pick a valid time." };
+  if (new Date(parsed.data.scheduledAt).getTime() <= Date.now()) {
+    return { ok: false, error: "Pick a time in the future." };
+  }
+
+  const supabase = await createClient();
+  const { error } = await supabase
+    .from("bookings")
+    .update({
+      scheduled_at: parsed.data.scheduledAt,
+      start_mode: "scheduled",
+    })
+    .eq("id", parsed.data.bookingId)
+    .eq("customer_id", profile.id)
+    .eq("status", "confirmed");
+  if (error) return { ok: false, error: "Could not reschedule." };
+
+  revalidatePath("/account");
+  return { ok: true };
+}
+
+/** Update the customer's display name. */
+export async function updateProfileName(
+  name: string,
+): Promise<{ ok: boolean; error?: string }> {
+  const profile = await requireRole("customer");
+  const trimmed = name.trim();
+  if (trimmed.length < 1 || trimmed.length > 120) {
+    return { ok: false, error: "Enter your name." };
+  }
+  const supabase = await createClient();
+  const { error } = await supabase
+    .from("profiles")
+    .update({ full_name: trimmed })
+    .eq("id", profile.id);
+  if (error) return { ok: false, error: "Could not save your name." };
+  revalidatePath("/account/settings");
+  return { ok: true };
+}

